    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return int(parsed.timestamp() // 1) if parsed.microsecond == 0 else int(
        (parsed - datetime(1970, 1, 1, tzinfo=UTC)) // timedelta(seconds=1))


