        if issued > cutoff:
            continue
        key = (row["site"], row["punch_id"])
        action = row["action"].lower()
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                punches[key][2] = parse_iso(row["time"])
                applied += 1
        elif action == "add":
            if key not in ever and row["site"] in sites:
                ever.add(key)
                punches[key] = [row["employee"], dir_of(row["type"]), parse_iso(row["time"])]
                applied += 1

    by_employee = {}
    for (site, punch_id), (badge, direction, instant) in punches.items():
        if badge in employees:
            by_employee.setdefault(badge, []).append(
                (instant, 0 if direction == "OUT" else 1, site, punch_id, direction))

    result = {}
    exceptions = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}
    for emp_id, home_site in employees.items():
        home_zone = sites[home_site][0]
        items = sorted(by_employee.get(emp_id, []))
        kept = []
        last = None
        for instant, _order, site, punch_id, direction in items:
            rounded = None
            zone = sites[site][0]
            local = instant + utc_offset(zone, instant)
            rounded = instant + ((local + 180) // 360 * 360 - local)
            workday = local_date(home_zone, rounded)
            if last is not None and last[4] == direction and instant - last[0] <= 300:
                if start <= workday <= end:
                    exceptions["duplicates_dropped"] += 1
                continue
            last = (instant, 0, site, punch_id, direction)
            kept.append((rounded, direction, site, workday))

        shifts = []
        index = 0
        while index < len(kept):
            rounded, direction, site, workday = kept[index]
            counted = start <= workday <= end
            if direction == "OUT":
                if counted:
                    exceptions["orphan_outs"] += 1
                index += 1
                continue
            nxt = kept[index + 1] if index + 1 < len(kept) else None
            if nxt is not None and nxt[1] == "OUT" and nxt[0] - rounded <= 16 * 3600:
                if counted:
                    shifts.append((rounded, nxt[0], site, workday))
                index += 2
            else:
                if counted:
                    exceptions["open_shifts"] += 1
                index += 1

        shifts.sort(key=lambda shift: shift[0])
        daily_used = {}
        details = []
        for rin, rout, site, workday in shifts:
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            zone = sites[site][0]
            night = 0
            cache = {}
            for minute_start in range(rin, rout, 60):
                bucket = minute_start // 900
                if bucket not in cache:
                    cache[bucket] = utc_offset(zone, minute_start)
                minute_of_day = ((minute_start + cache[bucket]) % 86400) // 60
                if minute_of_day < 360 or minute_of_day >= 1320:
                    night += 1
            night = min(night, paid)
            before = daily_used.get(workday, 0)
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            daily_used[workday] = before + paid
            details.append([workday, paid, daily_ot, night, 0])
        week_used = {}
        for detail in details:
            week = detail[0] - timedelta(days=detail[0].weekday())
            non_daily = detail[1] - detail[2]
            before = week_used.get(week, 0)
            weekly_ot = max(0, before + non_daily - 2400) - max(0, before - 2400)
            week_used[week] = before + non_daily
            detail[4] = weekly_ot

        paid_total = overtime_total = night_total = 0
        pay = Decimal(0)
        for workday, paid, daily_ot, night, weekly_ot in details:
            overtime = daily_ot + weekly_ot
            regular = paid - overtime
            rate = None
            for effective, value in rates.get(emp_id, []):
                if effective <= workday:
                    rate = value
            if rate is None:
                rate = Decimal(0)
            pay += rate * (Decimal(regular) + Decimal("1.5") * overtime) / 60
            pay += rate * Decimal("0.15") * night / 60
            paid_total += paid
            overtime_total += overtime
            night_total += night
        result[emp_id] = {
            "shifts": len(details),
            "paid_minutes": paid_total,
            "overtime_minutes": overtime_total,
            "night_minutes": night_total,
            "gross": pay.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
        }

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    gross = Decimal(0)
    for values in result.values():
        for field in totals:
            totals[field] += values[field]
        gross += values["gross"]
        values["gross"] = "%.2f" % values["gross"]
    totals["gross"] = "%.2f" % gross
    exceptions["corrections_applied"] = applied
    output = {"period": {"start": period["start"], "end": period["end"]},
              "employees": result, "exceptions": exceptions, "totals": totals}
    with open(output_file, "w") as handle:
        json.dump(output, handle, indent=1)


